SELECT 
FROM SYS_ENTERPRISE_INFO


        AND ENTERPRISE_NAME LIKE CONCAT('%', #{queryVO.enterpriseName}, '%')


        AND CREDIT_CODE = #{queryVO.creditCode}


        AND ENTERPRISE_TYPE = #{queryVO.enterpriseType}


        AND SUPERVISION_LEVEL = #{queryVO.supervisionLevel}


        AND REGION = #{queryVO.region}


        AND INDUSTRY = #{queryVO.industry}


        AND ENTERPRISE_STATUS = #{queryVO.enterpriseStatus}


        AND LEGAL_REPRESENTATIVE LIKE CONCAT('%', #{queryVO.legalRepresentative}, '%')


        AND LISTING_STATUS = #{queryVO.listingStatus}


        AND RISK_LEVEL = #{queryVO.riskLevel}


        AND IS_STATE_CONTROLLED = #{queryVO.isStateControlled}


        AND REGISTERED_CAPITAL >= #{queryVO.registeredCapitalMin}


        AND REGISTERED_CAPITAL <= #{queryVO.registeredCapitalMax}


        AND ESTABLISH_DATE >= #{queryVO.establishDateStart}


        AND ESTABLISH_DATE <= #{queryVO.establishDateEnd}


ORDER BY CREATE_TIME DESC

SELECT 
FROM SYS_ENTERPRISE_INFO


        AND (
            ENTERPRISE_NAME LIKE CONCAT('%', #{queryVO.keyword}, '%')
            OR CREDIT_CODE LIKE CONCAT('%', #{queryVO.keyword}, '%')
            OR LEGAL_REPRESENTATIVE LIKE CONCAT('%', #{queryVO.keyword}, '%')
            OR CONTACT_PHONE LIKE CONCAT('%', #{queryVO.keyword}, '%')
            OR ENTERPRISE_EMAIL LIKE CONCAT('%', #{queryVO.keyword}, '%')
        )


        AND ENTERPRISE_TYPE = #{queryVO.enterpriseType}


        AND REGION = #{queryVO.region}


        AND INDUSTRY = #{queryVO.industry}


        AND ENTERPRISE_STATUS = #{queryVO.enterpriseStatus}


ORDER BY CREATE_TIME DESC

SELECT 
FROM SYS_ENTERPRISE_INFO


        AND ENTERPRISE_NAME LIKE CONCAT('%', #{enterpriseName}, '%')


        AND CREDIT_CODE = #{creditCode}


        AND ENTERPRISE_TYPE = #{enterpriseType}


        AND REGION = #{region}


        AND INDUSTRY = #{industry}


        AND ENTERPRISE_STATUS = #{enterpriseStatus}


ORDER BY CREATE_TIME DESC
